import java.util.ArrayList;

/** Targeted check of the two scan paths the seeded harness doesn't cover. */
public class DrinkSpreadTest {
    static boolean ok = true;
    static void check(String label, boolean cond) {
        if (!cond) { ok = false; System.out.println("  FAIL: " + label); }
    }

    public static void main(String[] args) {
        // --- findWater: drink from the first adjacent lake ---
        Field f = new Field(20, 20);
        Gazelle g = new Gazelle(false, f, new Location(5, 5));
        Lake lake = new Lake(false, f, new Location(5, 6)); // adjacent
        lake.setVolume(100);
        int waterBefore = g.getWaterLevel();
        g.findWater();                       // Animal.findWater -> Organism.findWater drinks
        check("gazelle drank +15", g.getWaterLevel() == waterBefore + 15);
        check("lake reduced to 85", lake.getVolume() == 85);

        // findWater with no adjacent lake returns harmlessly (no neighbours)
        Field f2 = new Field(20, 20);
        Gazelle lonely = new Gazelle(false, f2, new Location(0, 0));
        int w2 = lonely.getWaterLevel();
        lonely.findWater();
        check("no lake -> no change", lonely.getWaterLevel() == w2);

        // --- Disease.spread: infect each adjacent occupant of an affected species ---
        Field f3 = new Field(20, 20);
        Lion carrier = new Lion(false, f3, new Location(5, 5));
        Gazelle victim = new Gazelle(false, f3, new Location(5, 6)); // adjacent, Covid affects Gazelle
        Covid covid = new Covid(f3);
        covid.setInfectiousness(1.0);        // make spread deterministic
        ArrayList<Actor> infected = covid.spread(carrier);
        check("spread infected exactly the adjacent gazelle",
            infected.size() == 1 && infected.get(0) == victim);

        System.out.println(ok
            ? "PASS: lake-drinking and disease-spread scans preserved via Field stream API."
            : "FAIL: see above.");
    }
}
